const TopologyPanel: React.FC<TopologyPanelProps> = ({ item, onClose, onGenerate }) => {
  const [selected, setSelected] = useState<TopologyStrategy[]>([]);
  const [isRecommending, setIsRecommending] = useState(false);

  const toggle = (id: TopologyStrategy) => {
    setSelected(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleRecommend = async () => {
    if (!item.content || isRecommending) return;
    setIsRecommending(true);
    try {
        const recommended = await recommendTopology(item.content);
        setSelected(recommended);
    } catch (e) {
        alert("智能推荐失败，请重试。");
    } finally {
        setIsRecommending(false);
    }
  };

  return (
    <div 
      className="absolute z-[300] bg-[#0c0c0e]/95 backdrop-blur-3xl border border-white/10 p-6 rounded-[32px] shadow-[0_40px_100px_rgba(0,0,0,0.8)] animate-in zoom-in-95 duration-300 pointer-events-auto flex flex-col gap-6 w-[480px] max-h-[85vh]"
      onMouseDown={e => e.stopPropagation()}
    >
      <div className="flex items-center justify-between shrink-0">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center">
            <RefreshIcon className="w-5 h-5 text-indigo-400" />
          </div>
          <div className="flex flex-col">
            <span className="text-white font-black text-[12px] uppercase tracking-[0.2em]">拓扑几何变体 (Topology)</span>
            <span className="text-zinc-500 text-[8px] font-bold uppercase tracking-widest mt-0.5">Industrial Composition Engine</span>
          </div>
        </div>
        <div className="flex items-center gap-2">
            <button 
                onClick={handleRecommend}
                disabled={isRecommending}
