  const getNextGlobalPointLabel = (items: CanvasItem[]): string => {
    let max = 0;
    items.forEach(it => {
        it.identifiedPoints?.forEach(p => {
            const num = parseInt(p.label, 10);
            if (!isNaN(num) && num > max) max = num;
        });
