                            className={`aspect-square rounded-xl bg-[#18181b] border flex items-center justify-center text-[10px] font-black transition-all ${JSON.stringify(selectedItem.spatialConfig) === JSON.stringify(v) ? 'border-indigo-500 text-indigo-400 bg-indigo-500/5' : 'border-white/5 text-zinc-500 hover:border-white/10'}`}
