            seed: Math.floor(Math.random() * 2147483647)
        };
        if (usePro) {
            config.imageConfig.imageSize = resolution;
        }

        const response = await ai.models.generateContent({ 
            model, 
            contents: [{ parts: [{ text: `${prompt}. ${spatialTxt} ${recipeInstruction || ''}. Style: ${styleSuffix}.` }] }], 
